package com.bosshighscore;

import com.google.common.collect.ImmutableSet;
import java.util.Set;

public enum BossCategory
{
	PVM,
	SKILLING,
	RAIDS;

	// By hiscore name rather than enum constant, so newer raids (The Fractured Archive) work with any RuneLite version
	private static final Set<String> SKILLING_BOSSES = ImmutableSet.of(
		"Wintertodt",
		"Tempoross",
		"Zalcano"
	);

	private static final Set<String> RAIDS_BOSSES = ImmutableSet.of(
		"Chambers of Xeric",
		"Chambers of Xeric: Challenge Mode",
		"Theatre of Blood",
		"Theatre of Blood: Hard Mode",
		"Tombs of Amascut",
		"Tombs of Amascut: Expert Mode",
		"The Fractured Archive"
	);

	/** By hiscore name, e.g. "Chambers of Xeric". */
	static BossCategory of(String bossName)
	{
		if (SKILLING_BOSSES.contains(bossName))
		{
			return SKILLING;
		}
		return RAIDS_BOSSES.contains(bossName) ? RAIDS : PVM;
	}
}

package com.bosshighscore;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(BossHighscoreConfig.GROUP)
public interface BossHighscoreConfig extends Config
{
	String GROUP = "bosshighscore";
	String TOP_BOSS_COUNT = "topBossCount";

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = TOP_BOSS_COUNT,
		name = "Top bosses shown",
		description = "How many bosses the dropdown under a player's name shows",
		position = 1
	)
	default int topBossCount()
	{
		return 5;
	}

	@Range(min = 1, max = 168)
	@ConfigItem(
		keyName = "refreshHours",
		name = "Refresh after (hours)",
		description = "On login, friends whose kills are older than this are looked up again",
		position = 2
	)
	default int refreshHours()
	{
		return 6;
	}

	@ConfigSection(
		name = "Bosses counted",
		description = "Which bosses count toward totals, top bosses and gains",
		position = 10
	)
	String BOSSES_SECTION = "bosses";

	@ConfigItem(
		keyName = "includePvm",
		name = "PvM bosses",
		description = "Every boss that isn't a skilling boss or a raid",
		section = BOSSES_SECTION,
		position = 11
	)
	default boolean includePvm()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeSkilling",
		name = "Skilling bosses",
		description = "Wintertodt, Tempoross and Zalcano",
		section = BOSSES_SECTION,
		position = 12
	)
	default boolean includeSkilling()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeRaids",
		name = "Raids",
		description = "Chambers of Xeric, Theatre of Blood and Tombs of Amascut, all modes",
		section = BOSSES_SECTION,
		position = 13
	)
	default boolean includeRaids()
	{
		return true;
	}
}

package com.bosshighscore;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.stream.Stream;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/** Search box, selected player card and the Friends / History lists. Only touch it on the Swing thread. */
class BossHighscorePanel extends PluginPanel
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm");
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMM");

	private final IconTextField searchField = new IconTextField();
	private final JLabel selectedNameLabel = new JLabel();
	private final JLabel selectedTotalLabel = new JLabel();
	private final JLabel statusLabel = new JLabel(" ");
	private final JPanel friendsList = createListPanel();
	private final JPanel historyList = createListPanel();

	private MaterialTabGroup tabGroup;
	private MaterialTab friendsTab;
	private MaterialTab historyTab;

	private final PanelActions actions;

	private PanelState state = PanelState.EMPTY;
	private String selectedName;
	private String expandedName;
	// The gains period whose per-boss list is open under the expanded player, or null
	private GainPeriod openPeriod;

	BossHighscorePanel(PanelActions actions)
	{
		this.actions = actions;
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(createHeader(), BorderLayout.NORTH);
		add(createTabs(), BorderLayout.CENTER);
		rebuild();
	}

	void render(PanelState state)
	{
		this.state = state;
		rebuild();
	}

	/** Shows the player in the tab they belong to: Friends for friends, History for everyone else. */
	void select(String name, boolean friend)
	{
		selectedName = name;
		expandedName = name;
		tabGroup.select(friend ? friendsTab : historyTab);
		rebuild();
	}

	/** For a searched player without boss kills: shown on the card, not added to a list. */
	void showWithoutKills(String name)
	{
		selectedName = name;
		expandedName = null;
		rebuild();
	}

	void setStatus(String text)
	{
		statusLabel.setText(text.isEmpty() ? " " : text);
	}

	private JPanel createHeader()
	{
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.addActionListener(e ->
		{
			actions.search(searchField.getText());
			searchField.setText("");
		});

		selectedNameLabel.setForeground(Color.WHITE);
		selectedTotalLabel.setForeground(ColorScheme.BRAND_ORANGE);
		selectedTotalLabel.setFont(FontManager.getRunescapeBoldFont());

		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(8, 8, 8, 8));
		card.add(selectedNameLabel, BorderLayout.WEST);
		card.add(selectedTotalLabel, BorderLayout.EAST);

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		header.add(searchField, BorderLayout.NORTH);
		header.add(card, BorderLayout.CENTER);
		header.add(statusLabel, BorderLayout.SOUTH);
		return header;
	}

	private JPanel createTabs()
	{
		JButton refreshButton = new JButton("Refresh friends");
		refreshButton.addActionListener(e -> actions.refreshFriends());

		JPanel friendsContent = new JPanel(new BorderLayout(0, 6));
		friendsContent.setOpaque(false);
		friendsContent.add(friendsList, BorderLayout.CENTER);
		friendsContent.add(refreshButton, BorderLayout.SOUTH);

		JButton clearButton = new JButton("Clear history");
		clearButton.addActionListener(e -> confirmClearHistory());

		JPanel historyContent = new JPanel(new BorderLayout(0, 6));
		historyContent.setOpaque(false);
		historyContent.add(historyList, BorderLayout.CENTER);
		historyContent.add(clearButton, BorderLayout.SOUTH);

		JPanel display = new JPanel(new BorderLayout());
		display.setOpaque(false);

		tabGroup = new MaterialTabGroup(display);
		friendsTab = new MaterialTab("Friends", tabGroup, friendsContent);
		historyTab = new MaterialTab("History", tabGroup, historyContent);
		tabGroup.addTab(friendsTab);
		tabGroup.addTab(historyTab);
		tabGroup.select(friendsTab);

		JPanel tabs = new JPanel(new BorderLayout(0, 6));
		tabs.setOpaque(false);
		tabs.add(tabGroup, BorderLayout.NORTH);
		tabs.add(display, BorderLayout.CENTER);
		return tabs;
	}

	private void rebuild()
	{
		fillList(friendsList, state.getFriends(), false, "Log in to load your friends list");
		fillList(historyList, state.getHistory(), true, "Search a player to start");
		showSelected();
		revalidate();
		repaint();
	}

	private void showSelected()
	{
		PlayerTotals selected = Stream.concat(state.getFriends().stream(), state.getHistory().stream())
			.filter(player -> player.getName().equalsIgnoreCase(selectedName))
			.findFirst()
			.orElse(null);

		if (selected != null)
		{
			selectedNameLabel.setText(selected.getName());
			selectedTotalLabel.setText(formatKills(selected.totalKills(state.getCategories())));
		}
		else
		{
			// Searched players without boss kills aren't in either list, but the card should still match the search
			selectedNameLabel.setText(selectedName == null ? "Search a player" : selectedName);
			selectedTotalLabel.setText(selectedName == null ? "" : "0");
		}
	}

	private void fillList(JPanel list, List<PlayerTotals> players, boolean removable, String emptyHint)
	{
		list.removeAll();
		if (players.isEmpty())
		{
			list.add(smallLabel(emptyHint, ColorScheme.LIGHT_GRAY_COLOR));
			return;
		}

		for (int i = 0; i < players.size(); i++)
		{
			list.add(createRow(String.valueOf(i + 1), players.get(i), removable));
		}
	}

	private JPanel createRow(String rankText, PlayerTotals player, boolean removable)
	{
		JLabel rankLabel = smallLabel(rankText, ColorScheme.LIGHT_GRAY_COLOR);
		rankLabel.setPreferredSize(new Dimension(16, 0));

		JLabel nameLabel = new JLabel(player.getName());
		nameLabel.setForeground(Color.WHITE);

		JPanel nameAndUpdated = new JPanel(new GridLayout(2, 1));
		nameAndUpdated.setOpaque(false);
		nameAndUpdated.add(nameLabel);
		nameAndUpdated.add(smallLabel(formatUpdated(player.getUpdatedMillis()), ColorScheme.LIGHT_GRAY_COLOR));

		JLabel totalLabel = new JLabel(formatKills(player.totalKills(state.getCategories())));
		totalLabel.setForeground(ColorScheme.BRAND_ORANGE);

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.setBorder(new EmptyBorder(4, 6, 4, 6));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setToolTipText("Left-click for top bosses, right-click to refresh");
		header.add(rankLabel, BorderLayout.WEST);
		header.add(nameAndUpdated, BorderLayout.CENTER);
		header.add(totalLabel, BorderLayout.EAST);
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					toggle(player.getName());
				}
				else if (SwingUtilities.isRightMouseButton(e))
				{
					rowMenu(player.getName(), removable).show(e.getComponent(), e.getX(), e.getY());
				}
			}
		});

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.add(header, BorderLayout.NORTH);
		if (player.getName().equalsIgnoreCase(expandedName))
		{
			row.add(createDetails(player), BorderLayout.CENTER);
		}
		return row;
	}

	private JPanel createDetails(PlayerTotals player)
	{
		JPanel details = new JPanel(new BorderLayout(0, 6));
		details.setOpaque(false);
		details.setBorder(new EmptyBorder(0, 28, 6, 6));
		details.add(createBossList(player), BorderLayout.CENTER);

		PlayerGains gains = state.getGains().get(PlayerStore.key(player.getName()));
		if (gains != null)
		{
			details.add(createGains(gains), BorderLayout.SOUTH);
		}
		return details;
	}

	private JPanel createBossList(PlayerTotals player)
	{
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 2));
		list.setOpaque(false);

		List<BossKills> topBosses = player.topBosses(state.getTopBossCount(), state.getCategories());
		for (int i = 0; i < topBosses.size(); i++)
		{
			BossKills boss = topBosses.get(i);
			JPanel line = new JPanel(new BorderLayout(6, 0));
			line.setOpaque(false);
			line.add(smallLabel((i + 1) + ". " + BossNames.shortName(boss.getBoss()), ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.CENTER);
			line.add(smallLabel(formatKills(boss.getKills()), Color.WHITE), BorderLayout.EAST);
			list.add(line);
		}
		return list;
	}

	private JPanel createGains(PlayerGains gains)
	{
		JPanel gainsPanel = new JPanel(new BorderLayout(0, 4));
		gainsPanel.setOpaque(false);
		if (openPeriod == null)
		{
			gainsPanel.add(createAllPeriods(gains), BorderLayout.NORTH);
			return gainsPanel;
		}

		// One period open: only its header and per-boss list, so they can't be mixed up with the other periods
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.add(clickable(smallLabel(openPeriod.getLabel(), ColorScheme.BRAND_ORANGE), openPeriod), BorderLayout.WEST);
		header.add(clickable(gainLabel("Total ", gainFor(gains, openPeriod)), openPeriod), BorderLayout.EAST);
		gainsPanel.add(header, BorderLayout.NORTH);
		gainsPanel.add(createBreakdown(gains, openPeriod), BorderLayout.CENTER);
		return gainsPanel;
	}

	private JPanel createAllPeriods(PlayerGains gains)
	{
		JPanel grid = new JPanel(new GridLayout(2, GainPeriod.values().length, 4, 0));
		grid.setOpaque(false);
		for (GainPeriod period : GainPeriod.values())
		{
			grid.add(clickable(smallLabel(period.getLabel(), ColorScheme.LIGHT_GRAY_COLOR), period));
		}
		for (GainPeriod period : GainPeriod.values())
		{
			grid.add(clickable(gainLabel("", gainFor(gains, period)), period));
		}
		return grid;
	}

	private int gainFor(PlayerGains gains, GainPeriod period)
	{
		return gains.gain(period, state.getCategories(), LocalDate.now(), ZoneId.systemDefault());
	}

	private static JLabel gainLabel(String prefix, int gain)
	{
		Color color = gain > 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR;
		return smallLabel(prefix + "+" + formatKills(gain), color);
	}

	/** Clicking a period opens its per-boss list; clicking it again closes it. */
	private JLabel clickable(JLabel label, GainPeriod period)
	{
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.setToolTipText(period == openPeriod ? "Click to show all periods" : "Click for gains per boss");
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				openPeriod = period == openPeriod ? null : period;
				rebuild();
			}
		});
		return label;
	}

	private JPanel createBreakdown(PlayerGains gains, GainPeriod period)
	{
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 2));
		list.setOpaque(false);

		GainBreakdown breakdown = gains.breakdown(period, state.getCategories(), LocalDate.now(), ZoneId.systemDefault());
		if (breakdown == null)
		{
			list.add(smallLabel("Per boss from the next lookups on", ColorScheme.LIGHT_GRAY_COLOR));
			return list;
		}
		if (breakdown.getBosses().isEmpty() && breakdown.getUnknownKills() <= 0)
		{
			list.add(smallLabel("No boss kills in this period", ColorScheme.LIGHT_GRAY_COLOR));
			return list;
		}
		for (BossKills boss : breakdown.getBosses())
		{
			list.add(breakdownLine(BossNames.shortName(boss.getBoss()), boss.getKills()));
		}
		if (breakdown.getUnknownKills() > 0)
		{
			list.add(breakdownLine("Earlier, boss unknown", breakdown.getUnknownKills()));
		}
		return list;
	}

	private static JPanel breakdownLine(String name, int kills)
	{
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.add(smallLabel(name, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.CENTER);
		line.add(gainLabel("", kills), BorderLayout.EAST);
		return line;
	}

	private void confirmClearHistory()
	{
		int choice = JOptionPane.showConfirmDialog(this,
			"Remove every player from your search history?", "Clear history",
			JOptionPane.YES_NO_OPTION);
		if (choice == JOptionPane.YES_OPTION)
		{
			actions.clearHistory();
		}
	}

	private JPopupMenu rowMenu(String name, boolean removable)
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem refresh = new JMenuItem("Refresh");
		refresh.addActionListener(e -> actions.refreshPlayer(name));
		menu.add(refresh);

		if (removable)
		{
			JMenuItem remove = new JMenuItem("Remove from history");
			remove.addActionListener(e -> actions.removeFromHistory(name));
			menu.add(remove);
		}
		return menu;
	}

	private void toggle(String name)
	{
		boolean wasExpanded = name.equalsIgnoreCase(expandedName);
		expandedName = wasExpanded ? null : name;
		openPeriod = null;
		selectedName = name;
		rebuild();
	}

	private static JPanel createListPanel()
	{
		JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		list.setOpaque(false);
		return list;
	}

	private static JLabel smallLabel(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	private static String formatKills(int kills)
	{
		return String.format("%,d", kills);
	}

	static String formatUpdated(long millis)
	{
		ZonedDateTime updated = Instant.ofEpochMilli(millis).atZone(ZoneId.systemDefault());
		boolean today = updated.toLocalDate().equals(LocalDate.now());
		return "updated " + (today ? TIME : DATE).format(updated);
	}
}

package com.bosshighscore;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/** Wires the parts together and passes RuneLite's events on; the work happens in the classes it injects. */
@PluginDescriptor(
	name = "Total Boss KC",
	description = "Total boss kills and top bosses for you, your friends and players you search",
	tags = {"boss", "kc", "killcount", "hiscore", "highscore", "friends", "total"}
)
public class BossHighscorePlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private PlayerStore store;

	@Inject
	private PanelPresenter presenter;

	@Inject
	private PlayerSearch search;

	@Inject
	private FriendsRefresher friends;

	@Inject
	private BossLookupMenu bossLookupMenu;

	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		store.load();
		BossHighscorePanel panel = new BossHighscorePanel(panelActions());
		presenter.attach(panel);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navigationButton = NavigationButton.builder()
			.tooltip("Total Boss KC")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		presenter.render();
		friends.start();
	}

	@Override
	protected void shutDown()
	{
		friends.stop();
		search.stop();
		clientToolbar.removeNavigation(navigationButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			friends.onLoginScreen();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			friends.onLoggedIn();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		friends.onGameTick();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Saved lookups are written to the same group; those already render themselves
		if (BossHighscoreConfig.GROUP.equals(event.getGroup()) && !PlayerStore.KEYS.contains(event.getKey()))
		{
			presenter.render();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Menu clicks run on the client thread; the toolbar is Swing
		bossLookupMenu.onMenuEntryAdded(event,
			() -> SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navigationButton)));
	}

	private PanelActions panelActions()
	{
		return new PanelActions()
		{
			@Override
			public void search(String name)
			{
				search.search(name);
			}

			@Override
			public void refreshFriends()
			{
				friends.refreshNow();
			}

			@Override
			public void refreshPlayer(String name)
			{
				search.lookUp(name);
			}

			@Override
			public void removeFromHistory(String name)
			{
				search.removeFromHistory(name);
			}

			@Override
			public void clearHistory()
			{
				search.clearHistory();
			}
		};
	}

	@Provides
	BossHighscoreConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossHighscoreConfig.class);
	}
}

package com.bosshighscore;

import lombok.Value;

@Value
public class BossKills
{
	String boss;
	int kills;

	// Worked out from the name, so saved lookups follow category changes without a new lookup
	public BossCategory getCategory()
	{
		return BossCategory.of(boss);
	}
}

package com.bosshighscore;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.util.Text;

/** Adds "Boss lookup" to the right-click menu of player names. */
@Singleton
class BossLookupMenu
{
	private static final String LOOKUP_OPTION = "Boss lookup";
	// Options that only show up on player names: chat, friends list, clan/friends chat and players in the world
	private static final Set<String> PLAYER_NAME_OPTIONS = ImmutableSet.of("Message", "Add ignore", "Remove friend", "Trade with");

	private final Client client;
	private final PlayerSearch search;

	@Inject
	BossLookupMenu(Client client, PlayerSearch search)
	{
		this.client = client;
		this.search = search;
	}

	/** @param openPanel shows the side panel; called on the client thread */
	void onMenuEntryAdded(MenuEntryAdded event, Runnable openPanel)
	{
		if (!PLAYER_NAME_OPTIONS.contains(Text.removeTags(event.getOption())))
		{
			return;
		}

		String name = MenuTargets.playerName(event.getTarget());
		if (name.isEmpty())
		{
			return;
		}

		// Index 0 is Cancel at the bottom, so 1 puts it last, right above Cancel
		client.createMenuEntry(1)
			.setOption(LOOKUP_OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(entry ->
			{
				openPanel.run();
				search.search(name);
			});
	}
}

package com.bosshighscore;

import java.io.IOException;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreResult;

/**
 * Hiscore lookups off the client thread, so spam clicking can't flood the hiscores or block RuneLite's shared
 * executor: searches during the 2 second cooldown are refused (see {@link SearchCountdown}), and friends are looked up one per second without
 * queueing the same player twice. Searches don't wait behind a friends refresh.
 */
@Slf4j
@Singleton
class BossLookupService
{
	private static final long SEARCH_COOLDOWN_MILLIS = 2000;
	private static final long BATCH_SPACING_MILLIS = 1000;

	private final HiscoreClient hiscoreClient;
	private final ScheduledExecutorService executor;
	private final AtomicLong lastSearchMillis = new AtomicLong();
	private final AtomicLong nextBatchMillis = new AtomicLong();
	private final Set<String> queued = ConcurrentHashMap.newKeySet();

	@Inject
	BossLookupService(HiscoreClient hiscoreClient, ScheduledExecutorService executor)
	{
		this.hiscoreClient = hiscoreClient;
		this.executor = executor;
	}

	/**
	 * For searches and Boss lookup: runs right away, unless the last search was under 2 seconds ago.
	 *
	 * @return false when on cooldown; the search is dropped, not queued
	 */
	boolean lookupSearch(String name, Consumer<PlayerTotals> onFound, Consumer<String> onMissing)
	{
		long now = System.currentTimeMillis();
		long previous = lastSearchMillis.get();
		if (now - previous < SEARCH_COOLDOWN_MILLIS || !lastSearchMillis.compareAndSet(previous, now))
		{
			return false;
		}
		executor.execute(() -> lookup(name, onFound, onMissing));
		return true;
	}

	long cooldownRemainingMillis()
	{
		return Math.max(0, lastSearchMillis.get() + SEARCH_COOLDOWN_MILLIS - System.currentTimeMillis());
	}

	/** For batches like the friends list. */
	void lookupBatch(String name, Consumer<PlayerTotals> onFound, Consumer<String> onMissing)
	{
		schedule(name, nextBatchMillis, BATCH_SPACING_MILLIS, onFound, onMissing);
	}

	private void schedule(String name, AtomicLong nextSlotMillis, long spacingMillis, Consumer<PlayerTotals> onFound,
		Consumer<String> onMissing)
	{
		String key = name.toLowerCase(Locale.ROOT);
		if (!queued.add(key))
		{
			return;
		}

		long now = System.currentTimeMillis();
		long slot = nextSlotMillis.updateAndGet(previous -> Math.max(previous + spacingMillis, now));
		executor.schedule(() ->
		{
			queued.remove(key);
			lookup(name, onFound, onMissing);
		}, slot - now, TimeUnit.MILLISECONDS);
	}

	private void lookup(String name, Consumer<PlayerTotals> onFound, Consumer<String> onMissing)
	{
		PlayerTotals totals;
		try
		{
			HiscoreResult result = hiscoreClient.lookup(name);
			if (result == null)
			{
				onMissing.accept(name);
				return;
			}
			totals = BossTotals.from(name, result, System.currentTimeMillis());
		}
		catch (IOException | RuntimeException e)
		{
			// RuntimeException too: a changed hiscore format must end the lookup, not leave it hanging
			log.warn("Hiscore lookup failed for {}", name, e);
			onMissing.accept(name);
			return;
		}
		onFound.accept(totals);
	}
}

