package com.bosshighscore;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.Value;

/**
 * Gains per period from only a handful of snapshots: the latest lookup, plus for each period the last lookup before
 * that period started. Until a period has such a lookup, its baseline is the first lookup ever made.
 */
@Value
public class PlayerGains
{
	KillSnapshot latest;
	Map<GainPeriod, KillSnapshot> baselines;
	/**
	 * The first lookup with per-boss counts, kept only while some starting point was saved without them, so older
	 * periods keep showing every boss known since then. Null otherwise.
	 */
	KillSnapshot firstWithBossDetail;

	static PlayerGains first(KillSnapshot snapshot)
	{
		Map<GainPeriod, KillSnapshot> baselines = new EnumMap<>(GainPeriod.class);
		for (GainPeriod period : GainPeriod.values())
		{
			baselines.put(period, snapshot);
		}
		return new PlayerGains(snapshot, baselines, null);
	}

	PlayerGains record(KillSnapshot next, ZoneId zone)
	{
		return record(next, zone, false);
	}

	/**
	 * For the lookup made at midnight: it becomes the starting point of the periods that just began, so kills from the
	 * evening before stay out of the new day.
	 */
	PlayerGains recordPeriodStart(KillSnapshot next, ZoneId zone)
	{
		return record(next, zone, true);
	}

	private PlayerGains record(KillSnapshot next, ZoneId zone, boolean nextStartsNewPeriods)
	{
		LocalDate latestDay = day(latest, zone);
		LocalDate nextDay = day(next, zone);
		KillSnapshot newPeriodStart = nextStartsNewPeriods ? next : latest;
		Map<GainPeriod, KillSnapshot> nextBaselines = new EnumMap<>(GainPeriod.class);
		for (GainPeriod period : GainPeriod.values())
		{
			boolean newPeriodStarted = latestDay.isBefore(period.start(nextDay));
			nextBaselines.put(period, withBossDetail(newPeriodStarted ? newPeriodStart : baselines.get(period)));
		}
		return new PlayerGains(next, nextBaselines, firstWithBossDetail(nextBaselines, next));
	}

	private KillSnapshot firstWithBossDetail(Map<GainPeriod, KillSnapshot> nextBaselines, KillSnapshot next)
	{
		if (nextBaselines.values().stream().allMatch(KillSnapshot::hasBossDetail))
		{
			return null;
		}
		if (firstWithBossDetail != null)
		{
			return firstWithBossDetail;
		}
		// The earliest per-boss lookup still known, e.g. yesterday's starting point for Today
		return Stream.concat(baselines.values().stream(), Stream.of(latest, next))
			.filter(KillSnapshot::hasBossDetail)
			.min(Comparator.comparingLong(KillSnapshot::getMillis))
			.orElse(null);
	}

	/**
	 * A starting point saved before gains per boss existed gets the latest lookup's per-boss counts when nothing was
	 * killed in between: kill counts only go up, so an equal total means every boss is equal too.
	 */
	private KillSnapshot withBossDetail(KillSnapshot baseline)
	{
		Set<BossCategory> all = EnumSet.allOf(BossCategory.class);
		if (baseline.hasBossDetail() || !latest.hasBossDetail() || baseline.total(all) != latest.total(all))
		{
			return baseline;
		}
		return KillSnapshot.of(baseline.getMillis(), latest.getBosses());
	}

	int gain(GainPeriod period, Set<BossCategory> categories, LocalDate today, ZoneId zone)
	{
		// No lookup yet in this period: nothing gained that we know of
		if (day(latest, zone).isBefore(period.start(today)))
		{
			return 0;
		}
		return latest.total(categories) - baselines.get(period).total(categories);
	}

	/**
	 * Every boss that went up in the period, most gained first. When the period's starting point was saved before gains
	 * per boss existed, the bosses count from the earliest later starting point that has them, and the kills before
	 * that are returned as unknown.
	 *
	 * @return null when no starting point in the period has per-boss counts yet
	 */
	GainBreakdown breakdown(GainPeriod period, Set<BossCategory> categories, LocalDate today, ZoneId zone)
	{
		if (day(latest, zone).isBefore(period.start(today)))
		{
			return new GainBreakdown(Collections.emptyList(), 0);
		}

		KillSnapshot baseline = baselines.get(period);
		KillSnapshot from = baseline.hasBossDetail() ? baseline : earliestWithBossDetailSince(baseline);
		if (from == null || !latest.hasBossDetail())
		{
			return null;
		}

		List<BossKills> bosses = latest.getBosses().entrySet().stream()
			.filter(boss -> categories.contains(BossCategory.of(boss.getKey())))
			.map(boss -> new BossKills(boss.getKey(), boss.getValue() - from.kills(boss.getKey())))
			.filter(gain -> gain.getKills() > 0)
			.sorted(Comparator.comparingInt(BossKills::getKills).reversed())
			.collect(Collectors.toList());
		return new GainBreakdown(bosses, from.total(categories) - baseline.total(categories));
	}

	private KillSnapshot earliestWithBossDetailSince(KillSnapshot baseline)
	{
		return Stream.concat(baselines.values().stream(), Stream.of(firstWithBossDetail))
			.filter(Objects::nonNull)
			.filter(KillSnapshot::hasBossDetail)
			.filter(snapshot -> snapshot.getMillis() >= baseline.getMillis())
			.min(Comparator.comparingLong(KillSnapshot::getMillis))
			.orElse(null);
	}

	private static LocalDate day(KillSnapshot snapshot, ZoneId zone)
	{
		return Instant.ofEpochMilli(snapshot.getMillis()).atZone(zone).toLocalDate();
	}
}

package com.bosshighscore;

import java.time.Duration;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Text;

/** Searching a player (search box, Boss lookup, right-click Refresh) and the search history. */
@Singleton
class PlayerSearch
{
	// A player searched again within this time is shown from the saved lookup instead of asking the hiscores again
	private static final Duration SEARCH_COOLDOWN = Duration.ofMinutes(1);

	private final PlayerStore store;
	private final BossLookupService lookups;
	private final SearchCountdown searchCountdown;
	private final PanelPresenter presenter;

	@Inject
	PlayerSearch(PlayerStore store, BossLookupService lookups, SearchCountdown searchCountdown, PanelPresenter presenter)
	{
		this.store = store;
		this.lookups = lookups;
		this.searchCountdown = searchCountdown;
		this.presenter = presenter;
	}

	void search(String typedName)
	{
		String name = Text.toJagexName(typedName.trim());
		if (name.isEmpty())
		{
			return;
		}

		// Searched before: show the saved kills straight away, the lookup below refreshes them
		PlayerTotals saved = store.get(name);
		if (saved != null && saved.hasBossKills())
		{
			showSearched(saved);
		}
		if (saved != null && !saved.isStale(System.currentTimeMillis(), SEARCH_COOLDOWN))
		{
			if (saved.hasBossKills())
			{
				presenter.setStatus("");
			}
			else
			{
				showWithoutKills(name);
			}
			return;
		}

		lookUp(name);
	}

	/** Asks the hiscores now, skipping the saved result; waits out the cooldown first if needed. */
	void lookUp(String name)
	{
		// Set before starting, so a fast result can't be overwritten by it
		presenter.setStatus("Looking up " + name + "...");
		boolean started = lookups.lookupSearch(name, totals ->
		{
			store.put(totals);
			if (totals.hasBossKills())
			{
				showSearched(totals);
				presenter.setStatus("");
			}
			else
			{
				showWithoutKills(name);
			}
		}, missing -> presenter.setStatus("No hiscores found for " + missing));

		if (!started)
		{
			searchCountdown.searchAfterCooldown(name, presenter::setStatus, this::lookUp);
		}
	}

	void removeFromHistory(String name)
	{
		store.removeFromHistory(name);
		presenter.render();
	}

	void clearHistory()
	{
		store.clearHistory();
		presenter.render();
	}

	void stop()
	{
		searchCountdown.stop();
	}

	private void showSearched(PlayerTotals totals)
	{
		String name = totals.getName();
		boolean friend = store.isFriend(name);
		if (!friend)
		{
			store.addToHistory(name);
		}
		presenter.render();
		presenter.select(name, friend);
	}

	private void showWithoutKills(String name)
	{
		presenter.setStatus(name + " has no boss kills on the hiscores");
		presenter.showWithoutKills(name);
	}
}

package com.bosshighscore;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.Duration;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/** Looked-up totals, search history and the last seen friends list, saved in the RuneLite config. */
@Slf4j
@Singleton
class PlayerStore
{
	private static final String PLAYERS_KEY = "players";
	private static final String HISTORY_KEY = "history";
	private static final String FRIENDS_KEY = "friends";
	private static final String GAINS_KEY = "gains";
	static final Set<String> KEYS = ImmutableSet.of(PLAYERS_KEY, HISTORY_KEY, FRIENDS_KEY, GAINS_KEY);
	private static final int HISTORY_LIMIT = 50;
	private static final Duration KEEP_UNUSED = Duration.ofDays(60);
	private static final Type PLAYERS_TYPE = new TypeToken<Map<String, PlayerTotals>>()
	{
	}.getType();
	private static final Type GAINS_TYPE = new TypeToken<Map<String, PlayerGains>>()
	{
	}.getType();
	private static final Type NAMES_TYPE = new TypeToken<List<String>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	private Map<String, PlayerTotals> players = new HashMap<>();
	private List<String> history = new ArrayList<>();
	private List<String> friends = new ArrayList<>();
	private Map<String, PlayerGains> gains = new HashMap<>();

	@Inject
	PlayerStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	synchronized void load()
	{
		players = read(PLAYERS_KEY, PLAYERS_TYPE, new HashMap<>());
		history = read(HISTORY_KEY, NAMES_TYPE, new ArrayList<>());
		friends = read(FRIENDS_KEY, NAMES_TYPE, new ArrayList<>());
		gains = read(GAINS_KEY, GAINS_TYPE, new HashMap<>());

		// Saved by an older version without a boss list: look them up again instead
		players.values().removeIf(totals -> totals.getBosses() == null);
		pruneUnused();
	}

	synchronized PlayerTotals get(String name)
	{
		return players.get(key(name));
	}

	/** Saves the lookup and moves the player's gain baselines along with it. */
	synchronized void put(PlayerTotals totals)
	{
		put(totals, false);
	}

	/** For the midnight lookup: it becomes the starting point of the day (and week, month, year) that just began. */
	synchronized void putAtMidnight(PlayerTotals totals)
	{
		put(totals, true);
	}

	private void put(PlayerTotals totals, boolean atMidnight)
	{
		String key = key(totals.getName());
		players.put(key, totals);

		KillSnapshot snapshot = totals.snapshot();
		PlayerGains previous = gains.get(key);
		ZoneId zone = ZoneId.systemDefault();
		if (previous == null)
		{
			gains.put(key, PlayerGains.first(snapshot));
		}
		else
		{
			gains.put(key, atMidnight ? previous.recordPeriodStart(snapshot, zone) : previous.record(snapshot, zone));
		}

		write(PLAYERS_KEY, players);
		write(GAINS_KEY, gains);
	}

	/** Keyed like {@link #key(String)}. */
	/**
	 * True when the player's last lookup was saved before gains per boss existed. Looking them up once more gives
	 * their gains a per-boss starting point straight away instead of waiting out the refresh time.
	 */
	synchronized boolean lacksBossDetail(String name)
	{
		PlayerGains playerGains = gains.get(key(name));
		return playerGains != null && !playerGains.getLatest().hasBossDetail();
	}

	synchronized Map<String, PlayerGains> gains()
	{
		return new HashMap<>(gains);
	}

	synchronized void addToHistory(String name)
	{
		history.removeIf(name::equalsIgnoreCase);
		history.add(0, name);
		if (history.size() > HISTORY_LIMIT)
		{
			history = new ArrayList<>(history.subList(0, HISTORY_LIMIT));
		}
		write(HISTORY_KEY, history);
	}

	synchronized void removeFromHistory(String name)
	{
		history.removeIf(name::equalsIgnoreCase);
		write(HISTORY_KEY, history);
	}

	synchronized void clearHistory()
	{
		history.clear();
		write(HISTORY_KEY, history);
	}

	synchronized void setFriends(List<String> names)
	{
		friends = new ArrayList<>(names);
		write(FRIENDS_KEY, friends);
	}

	/**
	 * Drops saved kills and gains of players that are neither a friend nor in the history and haven't been looked up
	 * for {@link #KEEP_UNUSED}, so the save can't grow forever. Not by friends list alone: right after login that list
	 * can still be half loaded, and dropping those friends would reset their gains.
	 */
	private void pruneUnused()
	{
		Set<String> named = new HashSet<>();
		friends.forEach(name -> named.add(key(name)));
		history.forEach(name -> named.add(key(name)));
		long cutoff = System.currentTimeMillis() - KEEP_UNUSED.toMillis();

		boolean playersChanged = players.entrySet()
			.removeIf(entry -> !named.contains(entry.getKey()) && entry.getValue().getUpdatedMillis() < cutoff);
		boolean gainsChanged = gains.keySet().retainAll(players.keySet());
		if (playersChanged)
		{
			write(PLAYERS_KEY, players);
		}
		if (gainsChanged)
		{
			write(GAINS_KEY, gains);
		}
	}

	synchronized boolean isFriend(String name)
	{
		return friends.stream().anyMatch(name::equalsIgnoreCase);
	}

	synchronized List<String> friendNames()
	{
		return new ArrayList<>(friends);
	}

	/** Searched players with known totals, newest search first. */
	synchronized List<PlayerTotals> history()
	{
		return known(history);
	}

	synchronized List<PlayerTotals> friends()
	{
		return known(friends);
	}

	private List<PlayerTotals> known(List<String> names)
	{
		return names.stream()
			.map(this::get)
			.filter(Objects::nonNull)
			.collect(Collectors.toList());
	}

	private <T> T read(String configKey, Type type, T fallback)
	{
		String json = configManager.getConfiguration(BossHighscoreConfig.GROUP, configKey);
		if (json == null)
		{
			return fallback;
		}
		try
		{
			T value = gson.fromJson(json, type);
			return value == null ? fallback : value;
		}
		catch (RuntimeException e)
		{
			// A damaged save must not stop the plugin from starting: start that part empty instead
			log.warn("Could not read saved {}, starting without it", configKey, e);
			return fallback;
		}
	}

	private void write(String configKey, Object value)
	{
		configManager.setConfiguration(BossHighscoreConfig.GROUP, configKey, gson.toJson(value));
	}

	static String key(String name)
	{
		return name.toLowerCase(Locale.ROOT);
	}
}

package com.bosshighscore;

import java.time.Duration;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;

/** One player's boss kills as the hiscores showed them at {@code updatedMillis}. Bosses are sorted, most kills first. */
@Value
public class PlayerTotals
{
	String name;
	List<BossKills> bosses;
	long updatedMillis;

	/** False when no boss reaches the hiscore minimum (5 kills). */
	public boolean hasBossKills()
	{
		return !bosses.isEmpty();
	}

	public int totalKills(Set<BossCategory> categories)
	{
		return bosses.stream()
			.filter(boss -> categories.contains(boss.getCategory()))
			.mapToInt(BossKills::getKills)
			.sum();
	}

	public List<BossKills> topBosses(int count, Set<BossCategory> categories)
	{
		return bosses.stream()
			.filter(boss -> categories.contains(boss.getCategory()))
			.limit(count)
			.collect(Collectors.toList());
	}

	public boolean isStale(long nowMillis, Duration maxAge)
	{
		return nowMillis - updatedMillis > maxAge.toMillis();
	}

	public KillSnapshot snapshot()
	{
		Map<String, Integer> kills = new HashMap<>();
		for (BossKills boss : bosses)
		{
			kills.put(boss.getBoss(), boss.getKills());
		}
		return KillSnapshot.of(updatedMillis, kills);
	}
}

package com.bosshighscore;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * A search clicked during the cooldown waits here; the latest click wins. It counts down in the panel's status line,
 * then searches when the cooldown is over.
 */
@Singleton
class SearchCountdown
{
	private static final long TICK_MILLIS = 200;

	private final ScheduledExecutorService executor;
	private final BossLookupService lookups;

	private String pendingName;
	private Consumer<String> onStatus;
	private Consumer<String> onSearch;
	private ScheduledFuture<?> ticker;

	@Inject
	SearchCountdown(ScheduledExecutorService executor, BossLookupService lookups)
	{
		this.executor = executor;
		this.lookups = lookups;
	}

	synchronized void searchAfterCooldown(String name, Consumer<String> onStatus, Consumer<String> onSearch)
	{
		this.pendingName = name;
		this.onStatus = onStatus;
		this.onSearch = onSearch;
		if (ticker == null)
		{
			ticker = executor.scheduleAtFixedRate(this::tick, 0, TICK_MILLIS, TimeUnit.MILLISECONDS);
		}
	}

	synchronized void stop()
	{
		if (ticker != null)
		{
			ticker.cancel(false);
			ticker = null;
		}
		pendingName = null;
	}

	private synchronized void tick()
	{
		long remaining = lookups.cooldownRemainingMillis();
		if (remaining > 0)
		{
			onStatus.accept("Looking up " + pendingName + " in " + (remaining + 999) / 1000 + "s...");
			return;
		}

		String name = pendingName;
		Consumer<String> search = onSearch;
		stop();
		search.accept(name);
	}
}

